style.css:
@-moz-document domain("google.com") {
html, body {
        background:
            radial-gradient(circle at 20% 20%, #263b68 0 1px, transparent 2px),
            radial-gradient(circle at 80% 35%, #ffffff 0 1px, transparent 2px),
            radial-gradient(circle at 45% 75%, #9db8df 0 1px, transparent 2px),
            #07101f !important;
        color: #d8e7ff !important;
        font-family: "ms sans serif", "tahoma", sans-serif !important;
    }

    body {
        background-size: 130px 130px, 190px 190px, 250px 250px, auto !important;
    }

    /* google search box */

    textarea,
    input[type="text"] {
        background: #d8d8d8 !important;
        color: #111 !important;
        border: 2px inset #808080 !important;
        border-radius: 0 !important;
        box-shadow: none !important;
    }

    textarea:focus,
    input[type="text"]:focus {
        outline: 1px dotted #000 !important;
    }

    /* buttons */

    button,
    input[type="submit"] {
        background: #c0c0c0 !important;
        color: #000 !important;
        border: 2px outset #ffffff !important;
        border-radius: 0 !important;
        font-family: "ms sans serif", "tahoma", sans-serif !important;
    }

    button:active,
    input[type="submit"]:active {
        border: 2px inset #ffffff !important;
    }

    /* links */

    a {
        color: #66aaff !important;
    }

    a:visited {
        color: #b28cff !important;
    }

    /* search results */

    div {
        scrollbar-color: #808080 #c0c0c0;
    }

    /* old windows-style selection */

    ::selection {
        background: #000080 !important;
        color: #ffffff !important;
    }
}
